    "autoRerun": {
      "type": "boolean",
      "title": "Re-run stale checks after each turn",
      "description": "When a mod's code changes after Validate or Test passed, re-run them at the end of Claude's turn (Validate first, then Test if it passes).",
      "default": true
    },
    "testTimeoutMinutes": {
      "type": "number",
      "title": "Check time limit (minutes)",
      "description": "A Validate, Test or type-check still running after this many minutes is stopped and shown as timed out. At most 10.",
      "default": 3
    },
    "logging": {
      "type": "string",
      "title": "Logging",
      "description": "off: nothing. normal: errors, session start and check results. verbose: also reports, scans, processes and commands. debug: also expected misses, lights and process output. Written to ~/.claude/mod-builder-data/logs/ and the debug log.",
      "options": [
        "off",
        "normal",
        "verbose",
        "debug"
      ],
      "default": "normal"
    }
  }
}

